// Se comprueba con Supabase que el token sea de alguien que existe y que sea
// super admin. NO se confía en nada que venga del navegador salvo el token:
// el rol se pregunta, no se acepta.
const b = $input.first().json.body || $input.first().json;
return [{ json: {
  accion:   String(b.accion || ''),
  instancia: String(b.instancia || '').trim(),
  token:    String(b.token || ''),
  webhook:  String(b.webhook || ''),
  firma:    String(b.firma || ''),
}}];

// El perfil llega de Supabase. Si no es super admin, se corta aquí.
const p = $input.first().json;
const e = $('Extraer').first().json;
const perfil = Array.isArray(p) ? p[0] : p;

if (!perfil || perfil.role !== 'super_admin' || perfil.status !== 'active') {
  return [{ json: { ok: false, motivo: 'no autorizado' } }];
}
// El nombre de la instancia se limpia: es lo que va en una URL de Evolution y
// no puede traer nada raro.
const inst = e.instancia.toLowerCase().replace(/[^a-z0-9-]/g, '');
if (!inst) return [{ json: { ok: false, motivo: 'falta el nombre de la instancia' } }];

return [{ json: { ok: true, accion: e.accion, instancia: inst, webhook: e.webhook, firma: e.firma } }];

// Cada acción es una llamada distinta a Evolution. Se arma aquí para que el
// nodo HTTP sea uno solo y no cuatro casi iguales.
const d = $input.first().json;
const base = $env.EVOLUTION_API_URL;
const inst = d.instancia;

let metodo = 'GET', url = '', cuerpo = null;

if (d.accion === 'crear') {
  // integration BAILEYS es la conexión por código QR, que es la que usa un
  // negocio con su número de siempre.
  metodo = 'POST';
  url = base + '/instance/create';
  cuerpo = {
    instanceName: inst,
    integration: 'WHATSAPP-BAILEYS',
    qrcode: true,
    // El webhook queda puesto DESDE EL PRIMER MOMENTO, con la firma. Dejarlo
    // para después es como se olvida y se termina con una instancia abierta
    // que nadie protege.
    webhook: {
      url: d.webhook,
      byEvents: false,
      base64: false,
      headers: { 'X-Toque-Signature': d.firma, 'Content-Type': 'application/json' },
      events: ['MESSAGES_UPSERT'],
    },
  };
} else if (d.accion === 'conectar') {
  url = base + '/instance/connect/' + inst;
} else if (d.accion === 'estado') {
  url = base + '/instance/connectionState/' + inst;
} else if (d.accion === 'desconectar') {
  metodo = 'DELETE';
  url = base + '/instance/logout/' + inst;
} else if (d.accion === 'webhook') {
  metodo = 'POST';
  url = base + '/webhook/set/' + inst;
  cuerpo = {
    webhook: {
      enabled: true, url: d.webhook, byEvents: false, base64: false,
      headers: { 'X-Toque-Signature': d.firma, 'Content-Type': 'application/json' },
      events: ['MESSAGES_UPSERT'],
    },
  };
}

return [{ json: { metodo, url, cuerpo, instancia: inst, accion: d.accion } }];

const r = $input.first().json;
const d = $('Decidir').first().json;

// Evolution devuelve el QR de formas distintas segun la version y la accion.
// Se normaliza para que la consola no tenga que saberlo.
const qr = r.base64 || (r.qrcode && (r.qrcode.base64 || r.qrcode.code)) || null;
const estado = r.state || (r.instance && r.instance.state) || r.connectionStatus || null;

return [{ json: {
  ok: true,
  accion: d.accion,
  instancia: d.instancia,
  qr: qr,
  estado: estado,
  crudo: r,
}}];
